        'checkpoints': checkpoints.map((e) => e.toJson()).toList(),
        if (ticketsIssued != null) 'ticketsIssued': ticketsIssued!,
        if (certified != null) 'certified': certified!.toJson(),
        if (ext != null) 'ext': ext!,
      };
}

/// A member or an administrator reads one election of the community whole: its
/// manifest, state, voting parameters, disclosure, the board checkpoints the community
/// kept and, once certified, the certified result. The outer document members (id,
/// type, issuer, recipient, issuedAt, expiresAt, proof) are owned by the framework —
/// SPEC §6.3.
class Payload {
  const Payload({
    required this.electionId,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        electionId: json['electionId'] as String,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final ElectionId electionId;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'electionId': electionId,
        if (ext != null) 'ext': ext!,
      };
}

