"The DID of the voting service that holds the board."},"trustees":{"\$ref":"#/\$defs/Trustees"},"binding":{"type":"boolean","description":"Whether the community treats the result as deciding something; creating a binding election takes another administrator\'s consent (VTI-VOT-081)."},"allowEarlyClose":{"type":"boolean"},"resultsBeforeClose":{"type":"boolean","description":"Open elections only: whether running totals may be read while voting is open (VTI-VOT-061)."},"textReleaseThreshold":{"type":"integer","minimum":10,"description":"Counted ballots required before any text answer is disclosed (VTI-VOT-065)."}}},"RollRule":{"title":"RollRule","description":"Who may be issued a ticket (VTI-VOT-021): the community\'s active members, its active members and the parties `listed` names, or only the parties `listed` names.","type":"object","additionalProperties":false,"required":["rule"],"properties":{"rule":{"type":"string","enum":["members","membersAndListed","listed"]},"listed":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2048,"description":"A DID enfranchised by name."},"uniqueItems":true}}},"SecrecyLevel":{"title":"SecrecyLevel","description":"`open`: ballots are recorded on the board as cast. `sealed`: ballots are encrypted to a jointly generated election key and decrypted after voting closes. `talliedEncrypted`: ballots are encrypted and only the totals are ever decrypted (VTI-VOT-060). Version 0.1 of the voting tasks carries open ballots only; a ballot box refuses to register any other level with `voting/election/register:unsupportedSecrecy` until the trustee tasks are specified.","type":"string","enum":["open","sealed","talliedEncrypted"]},"Question":{"title":"Question","description":"One question. Tagged union over `type`.","oneOf":[{"title":"ChoiceQuestion","description":"Select between `minSelections` and `maxSelections` of `options`. A yes/no/abstain motion is a choice of exactly one of three.","type":"object","additionalProperties":false,"required":["key","type","options","minSelections","maxSelections","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"choice"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":2,"maxItems":256,"items":{"\$ref":"#/\$defs/QuestionOption"}},"minSelections":{"type":"integer","minimum":0},"maxSelections":{"type":"integer","minimum":1},"optional":{"type":"boolean"}}},{"title":"RankingQuestion","description":"Order `options`; a ballot ranks every option or, when `partial` is true, a prefix of them.","type":"object","additionalProperties":false,"required":["key","type","options","partial","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"ranking"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":2,"maxItems":64,"items":{"\$ref":"#/\$defs/QuestionOption"}},"partial":{"type":"boolean"},"optional":{"type":"boolean"}}},{"title":"ScoreQuestion","description":"Give each option an integer score within [min, max].","type":"object","additionalProperties":false,"required":["key","type","options","min","max","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"score"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/QuestionOption"}},"min":{"type":"integer"},"max":{"type":"integer"},"optional":{"type":"boolean"}}},{"title":"TextQuestion","description":"Free text of at most `maxLength` characters.","type":"object","additionalProperties":false,"required":["key","type","maxLength","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"text"},"text":{"type":"string","maxLength":2048},"maxLength":{"type":"integer","minimum":1,"maximum":4096},"optional":{"type":"boolean"}}}]},"Key":{"title":"Key","description":"A question or option key, unique within its manifest or question.","type":"string","pattern":"^[A-Za-z0-9._-]{1,64}\$"},"QuestionOption":{"title":"QuestionOption","type":"object","additionalProperties":false,"required":["key"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"label":{"type":"string","maxLength":512,"description":"Display text. Absent from a manifest registered with a ballot box that holds no question text (VTI-VOT-014)."}}},"ElectionId":{"title":"ElectionId","description":"An election\'s identifier, unique within its community. A closed alphabet: it appears in the ticket class label `voter/<electionId>` and is framed into every hash a cast is bound to.","type":"string","pattern":"^[A-Za-z0-9._-]{1,128}\$"},"ElectionResult":{"title":"ElectionResult","description":"An election\'s result, computable by anyone who can read its board from the board and the registration alone (VTI-VOT-070).","type":"object","additionalProperties":false,"required":["electionId","manifestDigest","ballotsCounted","questions","head"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"manifestDigest":{"\$ref":"#/\$defs/DigestMultibase"},"ballotsCounted":{"type":"integer","minimum":0},"questions":{"type":"array","items":{"\$ref":"#/\$defs/QuestionResult"}},"head":{"\$ref":"#/\$defs/BoardHead","description":"The head of the board as it stood at close: the result counts exactly its entries."}}},"BoardHead":{"title":"BoardHead","description":"A board\'s tree head (RFC 9162 §2.1). A head is signed by being carried in a document the ballot box signs; whoever keeps a head keeps that whole document.","type":"object","additionalProperties":false,"required":["electionId","treeSize","rootHash","issuedAt"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"treeSize":{"type":"integer","minimum":0},"rootHash":{"\$ref":"#/\$defs/DigestMultibase","description":"The RFC 9162 Merkle tree hash (SHA-256) of the first `treeSize` entries, as a multihash."},"issuedAt":{"type":"string","format":"date-time"}}},"QuestionResult":{"title":"QuestionResult","description":"One question\'s totals. `choice`: selections per option. `ranking`: per option, how many ballots placed it at each position (index 0 = first). `score`: per option, the sum and the number of ballots that scored it. `text`: the answers, in board order, withheld (`withheld: true`) below the manifest\'s `textReleaseThreshold`. `abstained` counts ballots that left the question unanswered.","type":"object","additionalProperties":false,"required":["question","abstained"],"properties":{"question":{"\$ref":"#/\$defs/Key"},"abstained":{"type":"integer","minimum":0},"choice":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"integer","minimum":0}},"ranking":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"array","items":{"type":"integer","minimum":0}}},"score":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"object","additionalProperties":false,"required":["sum","count"],"properties":{"sum":{"type":"integer"},"count":{"type":"integer","minimum":0}}}},"text":{"type":"array","items":{"type":"string","maxLength":4096}},"withheld":{"type":"boolean"}}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
